import sys

def extract_function(filename, func_name):
    with open(filename, 'r') as f:
        lines = f.readlines()

    start_line = -1
    for i, line in enumerate(lines):
        if line.strip().startswith(f"def {func_name}") or line.strip().startswith(f"@triton.jit()"):
            # Check if the next line or the current line contains the function name
            if f"def {func_name}" in line:
                # For @triton.jit(), we need to include the decorator
                if i > 0 and "@triton.jit()" in lines[i-1]:
                    start_line = i - 1
                else:
                    start_line = i
                break

    if start_line == -1:
        return None

    # Find the end of the function by looking at indentation
    indent = None
    func_body = []
    for i in range(start_line, len(lines)):
        line = lines[i]
        if i == start_line:
            func_body.append(line)
            continue

        if line.strip() == "":
            func_body.append(line)
            continue

        current_indent = len(line) - len(line.lstrip())
        if indent is None:
            if line.strip():
                indent = current_indent

        if indent is not None and current_indent < indent and line.strip():
            break

        func_body.append(line)

    return "".join(func_body)

